        <select data-ajuste="direccion">
          ${[["joystick","Joystick"],["botones","Botones izquierda y derecha"]].map(([x,v])=>`<option value="${x}"${(e.direccion||"joystick")===x?" selected":""}>${v}</option>`).join("")}
        </select>
